export const DESKTOP_GROUP = "Desktop Entry";

export const MetaKey = {
  kind: "X-IconMatcher-Kind",
  source: "X-IconMatcher-Source",
  wmClass: "X-IconMatcher-WMClass",
  matchType: "X-IconMatcher-MatchType",
  score: "X-IconMatcher-Score",
} as const;

export type EntryKind = "ghost";

export interface EntryMetadata {
  kind: EntryKind;
  source: string;
  wmClass: string;
  matchType: string;
  score: number;
}

export function headerComment(meta: EntryMetadata): string {
  return [
    " Auto-generated by the Icon Matcher GNOME Shell extension.",
    ` Source: ${meta.source}`,
    ` Hidden copy with StartupWMClass=${meta.wmClass} so GNOME Shell can match its windows.`,
    " Delete this file (or use Reset in the extension preferences) to undo it.",
  ].join("\n");
}

export function parseLegacyHeader(text: string): Partial<EntryMetadata> {
  const field = (regex: RegExp) => text.match(regex)?.[1]?.trim();

  const meta: Partial<EntryMetadata> = {};
  const source = field(/^# Source:\s*(.+)$/m);
  const matchType = field(/^# Search type:\s*(.+)$/m);
  const score = Number(field(/^# Score[^:]*:\s*(\d+)\s*$/m));

  if (source) meta.source = source;
  if (matchType) meta.matchType = matchType;
  if (Number.isFinite(score) && score > 0) meta.score = score;
  return meta;
}
